<script setup>
import {computed} from 'vue'
import {financeRows} from '../services/quarterly-report.js'
const props=defineProps({report:{type:Object,required:true}})
const rows=computed(()=>financeRows(props.report))
const max=computed(()=>Math.max(1,...rows.value.map(x=>Math.abs(Number(x[1])||0))))
</script>
<template><section><p>{{report.basis?.quarter||report.quarter}} · 核算{{report.calculationId}} · 版本{{report.version}}<span v-if="report.status||report.reviewed"> · {{report.reviewed?'财务已复核':report.status}}</span></p><div class="cards"><article v-for="[label,value] in rows" :key="label"><span>{{label}}</span><strong>{{value??'待核实'}}<small v-if="value!=null"> 元</small></strong></article></div><h3>金额对比</h3><div v-for="[label,value] in rows" :key="label" class="bar-row"><span>{{label}}</span><div class="track"><div :class="{negative:Number(value)<0}" :style="{width:Math.abs(Number(value)||0)/max*100+'%'}"></div></div><span>{{value??'待核实'}}</span></div><h3>牙医业绩</h3><table><thead><tr><th>牙医编号</th><th>业绩（元）</th></tr></thead><tbody><tr v-for="item in report.performance||[]" :key="item.dentistId"><td>{{item.dentistId}}</td><td>{{item.amount}}</td></tr></tbody></table><details><summary>来源与核算口径</summary><p>统计快照 {{report.statisticId||report.basis?.statisticId}} · 来源版本 {{report.basis?.sourceVersion||report.sourceVersion}}</p><p>运营费用与耗用成本分别归集；业绩按实际接诊牙医归属。</p></details></section></template>
<style scoped>.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px}article{padding:16px;background:#eef5f1;border-radius:12px;display:grid;gap:8px}strong{font-size:1.5rem}small{font-size:.8rem;font-weight:normal}.bar-row{display:grid;grid-template-columns:8rem 1fr 6rem;gap:8px;align-items:center;margin:10px 0}.track{background:#eef1ef;height:14px;border-radius:8px}.track>div{height:100%;background:#1a786b;border-radius:8px}.track>.negative{background:#a94b34}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #ccd8d2;text-align:left}</style>
